import{_ as n,a0 as p,w as r,s as d,ao as l,I as a,a1 as t,A as o,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"如何在 Debian 和 Kali Linux 上安裝 Chrome 瀏覽器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Debian 和 Kali Linux 上安裝 Chrome 瀏覽器 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Debian 和 Kali Linux 上安裝 Chrome 瀏覽器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Debian 和 Kali Linux 上安裝 Chrome 瀏覽器 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20211001 How to Install Google Chrome on Debian and Kali Linux","title":"如何在 Debian 和 Kali Linux 上安裝 Chrome 瀏覽器","tag":"202110","desc":""},"relativePath":"202110/20211001 How to Install Google Chrome on Debian and Kali Linux.md","filePath":"[post].md"}'),m={name:"202110/20211001 How to Install Google Chrome on Debian and Kali Linux.md"};function h(u,e,b,g,C,f){const s=p("Link");return r(),d("div",null,[e[29]||(e[29]=l('<h1 id="如何在-debian-和-kali-linux-上安裝-chrome-瀏覽器" tabindex="-1">如何在 Debian 和 Kali Linux 上安裝 Chrome 瀏覽器 <a class="header-anchor" href="#如何在-debian-和-kali-linux-上安裝-chrome-瀏覽器" aria-label="Permalink to “如何在 Debian 和 Kali Linux 上安裝 Chrome 瀏覽器”">​</a></h1><blockquote><p>Debian 和基於 Debian 的 Kali Linux 將 Firefox 作為默認的網頁瀏覽器。但這並不意味着你不能在其中安裝其他網頁瀏覽器。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202110/18/175716cfvxnvf05b5je1ax.jpg" alt=""></p><p>Chrome 瀏覽器非常流行，你可能已經在其他系統上使用它了。如果你想在 Debian 上安裝 Chrome，你肯定可以這樣做。</p><p>你在 Debian 的軟件庫中找不到 Chrome，因為它不是開源軟件，但你可以從 Chrome 網站下載並安裝它。</p><p>在本教程中，我將向你展示在 Debian 上安裝 Chrome 的兩種方法：</p><ul><li>GUI 方法</li><li>命令列方法</li></ul><p>讓我們先從 GUI 方法開始。</p><blockquote><p>注意：我在這裏的例子中使用的是 Debian，但由於 Kali Linux 是基於 Debian 的，所以同樣的方法也適用於 Kali Linux。</p></blockquote><h3 id="方法-1-在-debian-上以圖形方式安裝-chrome-瀏覽器" tabindex="-1">方法 1: 在 Debian 上以圖形方式安裝 Chrome 瀏覽器 <a class="header-anchor" href="#方法-1-在-debian-上以圖形方式安裝-chrome-瀏覽器" aria-label="Permalink to “方法 1: 在 Debian 上以圖形方式安裝 Chrome 瀏覽器”">​</a></h3><p>這是一個不費吹灰之力的方法。你去 Chrome 網站，下載 deb 文件，然後雙擊它來安裝它。我將詳細地展示這些步驟，這樣你就能很容易地掌握了。</p><p>前往 Chrome 的網站。</p>',12)),a("p",null,[t(s,{href:"https://www.google.com/chrome/"},{default:o(()=>[...e[0]||(e[0]=[i("Get Google Chrome",-1)])]),_:1})]),e[30]||(e[30]=l('<p>你會看到下載 Chrome 的選項。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/download-chrome-on-debian.webp?resize=800%2C344&amp;ssl=1" alt="Click on the Download Chrome button"></p><p>當你點擊下載按鈕時，它會給你兩個下載安裝文件的選項。選擇寫着 Debian/Ubuntu 的那個。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/downloading-google-chrome.webp?resize=800%2C512&amp;ssl=1" alt="Download the Chrome installer file for Debian"></p><p><strong>請注意，Chrome 瀏覽器不適用於 32 位系統。</strong></p><p>接下來，你應該選擇將文件保存到電腦中，而不是在軟件中心打開進行安裝。這樣一來，下載的文件將被保存在下載文件夾中，而不是臨時目錄中。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/save-downloaded-chrome-installer-file-debian.webp?resize=800%2C430&amp;ssl=1" alt="Save the downloaded DEB file for Google Chrome"></p><p>進入下載文件夾，右擊下載的 DEB 文件，選擇用 “Software Install” 打開它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/open-deb-file-with-software-install.webp?resize=800%2C419&amp;ssl=1" alt="Right click on the downloaded DEB file and open with Software Install"></p><p>它將打開軟件中心，你應該看到現在安裝 Chrome 瀏覽器的選項。點擊安裝按鈕。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/installing-chrome-debian.webp?resize=800%2C408&amp;ssl=1" alt="Click on the install button"></p><p>你會被要求輸入賬户的密碼。這是你用來登錄系統的同一密碼。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/enter-account-password-while-installing-deb-file.webp?resize=800%2C420&amp;ssl=1" alt="Enter your account’s password"></p><p>在不到一分鐘的時間裏，Chrome 就會安裝完畢。你現在應該看到一個刪除選項，這表明軟件已經安裝完畢。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/09/chrome-installed-debian.webp?resize=800%2C384&amp;ssl=1" alt="Chrome is now installed"></p><p>當 Chrome 在 Debian 上安裝完畢，在系統菜單中搜索它並啓動它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/start-chrome-debian.webp?resize=800%2C276&amp;ssl=1" alt="Start Google Chrome"></p><p>它將要求成為你的默認瀏覽器，並將崩潰報告發送給谷歌。你可以取消勾選這兩個選項。然後你就可以看到谷歌瀏覽器的窗口。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/09/Chrom-in-Debian.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p>如果你登錄了你的谷歌賬户，你應該可以在這裏同步你的密碼、書籤和其他瀏覽數據。好好體驗吧！</p><p>還有一點，安裝完 Chrome 後，你可以從系統中刪除下載的 DEB 文件。不再需要它了，甚至在卸載 Chrome 時也不需要。</p><h3 id="方法-2-在-debian-上從終端安裝-chrome" tabindex="-1">方法 2：在 Debian 上從終端安裝 Chrome <a class="header-anchor" href="#方法-2-在-debian-上從終端安裝-chrome" aria-label="Permalink to “方法 2：在 Debian 上從終端安裝 Chrome”">​</a></h3><p>你剛才看到的內容可以在終端中輕鬆實現。</p>',23)),a("p",null,[e[2]||(e[2]=i("首先，確保你的軟件包緩存已經刷新，並且你已經安裝了 ",-1)),e[3]||(e[3]=a("code",null,"wget",-1)),e[4]||(e[4]=i("，用於 ",-1)),t(s,{href:"https://itsfoss.com/download-files-from-linux-terminal/"},{default:o(()=>[...e[1]||(e[1]=[i("在終端中從網上下載文件",-1)])]),_:1}),e[5]||(e[5]=i("。",-1))]),e[31]||(e[31]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt install wget</span></span></code></pre></div><p>接下來是下載 Chrome 的 .deb 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget https://dl.google.com/linux/direct/google-chrome-stable_current_amd64.deb</span></span></code></pre></div>',3)),a("p",null,[e[7]||(e[7]=i("下載後，你可以用 ",-1)),e[8]||(e[8]=a("code",null,"apt",-1)),e[9]||(e[9]=i(" 命令 ",-1)),t(s,{href:"https://itsfoss.com/install-deb-files-ubuntu/"},{default:o(()=>[...e[6]||(e[6]=[i("在終端安裝 deb 文件",-1)])]),_:1}),e[10]||(e[10]=i("，像這樣：",-1))]),e[32]||(e[32]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ./google-chrome-stable_current_amd64.deb</span></span></code></pre></div><p>安裝完成後，你就可以開始使用 Chrome 了。</p><h3 id="額外提示-更新-chrome" tabindex="-1">額外提示：更新 Chrome <a class="header-anchor" href="#額外提示-更新-chrome" aria-label="Permalink to “額外提示：更新 Chrome”">​</a></h3><p>這兩種方法都會將谷歌的軟件庫添加到你的系統中。你可以在你的 <code>sources.list.d</code> 目錄中看到它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/apt/sources.list.d/google-chrome.list</span></span></code></pre></div>',5)),a("p",null,[e[12]||(e[12]=i("這意味着 Chrome 將與 Debian 和 Kali Linux 中的其他系統更新一起被更新。你知道 ",-1)),t(s,{href:"https://linuxhandbook.com/update-kali-linux/"},{default:o(()=>[...e[11]||(e[11]=[i("如何在命令列中更新你的 Kali Linux",-1)])]),_:1}),e[13]||(e[13]=i(" 或 Debian 系統麼？只要使用這個命令：",-1))]),e[33]||(e[33]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><h3 id="從你的系統中卸載-chrome" tabindex="-1">從你的系統中卸載 Chrome <a class="header-anchor" href="#從你的系統中卸載-chrome" aria-label="Permalink to “從你的系統中卸載 Chrome”">​</a></h3><p>即使你選擇用 GUI 方法在 Debian 上安裝 Chrome，你也必須使用終端來刪除它。</p><p>不要擔心。這其實只是一個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge google-chrome-stable</span></span></code></pre></div><p>根據要求輸入你的賬户密碼。當你輸入密碼時，屏幕上沒有任何顯示。這沒關係。輸入它並按回車鍵，確認刪除。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/remove-google-chrome-ubuntu.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p>好了，就這些了。我希望你覺得這個教程有幫助。</p><hr>',9)),a("p",null,[e[15]||(e[15]=i("via: ",-1)),t(s,{href:"https://itsfoss.com/install-chrome-debian-kali-linux/"},{default:o(()=>[...e[14]||(e[14]=[i("https://itsfoss.com/install-chrome-debian-kali-linux/",-1)])]),_:1})]),a("p",null,[e[20]||(e[20]=i("作者：",-1)),t(s,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...e[16]||(e[16]=[i("Abhishek Prakash",-1)])]),_:1}),e[21]||(e[21]=i(" 選題：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[17]||(e[17]=[i("lujun9972",-1)])]),_:1}),e[22]||(e[22]=i(" 譯者：",-1)),t(s,{href:"https://github.com/geekpi"},{default:o(()=>[...e[18]||(e[18]=[i("geekpi",-1)])]),_:1}),e[23]||(e[23]=i(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:o(()=>[...e[19]||(e[19]=[i("wxy",-1)])]),_:1})]),a("p",null,[e[26]||(e[26]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[24]||(e[24]=[i("LCTT",-1)])]),_:1}),e[27]||(e[27]=i(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:o(()=>[...e[25]||(e[25]=[i("Linux中國",-1)])]),_:1}),e[28]||(e[28]=i(" 榮譽推出",-1))])])}const x=n(m,[["render",h]]);export{c as __pageData,x as default};
